namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var result = new List<string>();
        int remaining = item.OnHand - item.Reserved;

        if (remaining <= 0)
            return result;

        foreach (var zone in warehouse.Zones)
        {
            if (!TryCalculatePlacement(zone.Name, zone.Capacity, remaining, out int place))
                continue;

            result.Add($"{zone.Name}:{place}");
            remaining -= place;

            if (remaining <= 0)
                break;
        }

        if (remaining > 0)
            result.Add($"OVERFLOW:{remaining}");

        return result;
    }

    private static bool TryCalculatePlacement(
        string? zoneName,
        int capacity,
        int remaining,
        out int place)
    {
        place = 0;
        if (capacity <= 0 || string.IsNullOrEmpty(zoneName))
            return false;

        place = CalculatePlacement(capacity, remaining);
        return place > 0;
    }

    private static int CalculatePlacement(int capacity, int remaining)
    {
        if (remaining > capacity)
            return capacity;

        if (remaining > capacity / 2)
            return remaining - 1;

        return remaining;
    }
}
